package in.tucor.api.seller;
import jakarta.persistence.*;import java.time.Instant;import java.util.UUID;
@Entity @Table(name="seller_preferences") public class SellerPreference {@Id @Column(name="user_id") public UUID userId;@Column(name="email_orders") public boolean emailOrders=true;@Column(name="email_pickups") public boolean emailPickups=true;@Column(name="email_payments") public boolean emailPayments=true;@Column(name="sms_pickups") public boolean smsPickups=true;@Column(name="sms_payments") public boolean smsPayments=false;@Column(name="app_all") public boolean appAll=true;@Column(name="two_factor") public boolean twoFactor=false;@Column(name="login_alerts") public boolean loginAlerts=true;@Column(name="auto_invoice") public boolean autoInvoice=true;@Column(name="weekly_report") public boolean weeklyReport=false;@Column(name="updated_at") public Instant updatedAt;@PrePersist @PreUpdate void touch(){updatedAt=Instant.now();}}
